[CmdletBinding()]param([Parameter(Mandatory)][string]$Repository,[Parameter(Mandatory)][string]$RunId,[Parameter(Mandatory)][string]$Workflow,[Parameter(Mandatory)][string]$RunNamePrefix)
if(-not $env:GITHUB_TOKEN -or -not $env:GITHUB_OUTPUT){throw 'GITHUB_TOKEN and GITHUB_OUTPUT are required'};$api=if($env:GITHUB_API_URL){$env:GITHUB_API_URL}else{'https://api.github.com'};$headers=@{Accept='application/vnd.github+json';Authorization="Bearer $env:GITHUB_TOKEN";'X-GitHub-Api-Version'='2022-11-28'};$flows=Invoke-RestMethod -Headers $headers -Uri "$api/repos/$Repository/actions/workflows?per_page=100";$wf=@($flows.workflows|Where-Object{$_.path -eq $Workflow -or $_.path.EndsWith("/$Workflow")}|Select-Object -First 1);if(-not $wf.Count){throw "Workflow not found: $Workflow"};$run=Invoke-RestMethod -Headers $headers -Uri "$api/repos/$Repository/actions/runs/$([uri]::EscapeDataString($RunId))";if($run.workflow_id -ne $wf[0].id){throw "Workflow run $RunId is not a $Workflow run."};if($run.event -ne 'push'){throw "Workflow run $RunId was triggered by $($run.event), not a branch push."};if($run.conclusion -ne 'success'){throw "Workflow run $RunId did not succeed."};if(-not $run.head_branch -or $run.head_branch -eq 'main'){throw "Workflow run $RunId must be a successful non-main branch push."};if(-not $run.display_title -or -not $run.display_title.StartsWith($RunNamePrefix)){throw "Workflow run $RunId predates the integrated branch-validation workflow and cannot be used for dev artifacts."};$slug=($run.head_branch.ToLowerInvariant() -replace '[^a-z0-9_.-]+','-' -replace '^[.-]+|[.-]+$','');if(-not $slug){$slug='branch'};$max=[math]::Max(1,128-"dev--$($run.head_sha)".Length);$image="dev-$($slug.Substring(0,[math]::Min($slug.Length,$max)))-$($run.head_sha)";Add-Content -LiteralPath $env:GITHUB_OUTPUT -Value "source_sha=$($run.head_sha)`nsource_branch=$($run.head_branch)`nsource_run_id=$RunId`ndev_image_tag=$image" -Encoding utf8
